import React, { useState, useMemo } from "react";
import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";
import products from "../products/Products";
import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

import { Link } from "react-router-dom";



/* ============================================================
   FONTS
   ============================================================ */

const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORY DATA (الأيقونات فقط - البيانات نفسها بتيجي من products.js)
   ============================================================ */

const CATEGORIES = [
  { id: "All", label: "All", icon: Sparkles },
  { id: "Rings", label: "Rings", icon: Gem },
  { id: "Necklaces", label: "Necklaces", icon: Sparkles },
  { id: "Bracelets", label: "Bracelets", icon: CircleDot },
  { id: "Earrings", label: "Earrings", icon: Star },
  { id: "Chains", label: "Chains", icon: Link2 },
  { id: "Watches", label: "Watches", icon: Watch },
];

// خريطة: اسم الفئة -> الأيقونة المستخدمة في كارت المنتج
const CATEGORY_ICON = {
  Rings: Gem,
  Necklaces: Sparkles,
  Bracelets: CircleDot,
  Earrings: Star,
  Chains: Link2,
  Watches: Watch,
};

// تحويل بيانات products.js (title/thumbnail) لنفس الشكل اللي التصميم بيستخدمه (name/image)
const PRODUCTS = products.map((p) => ({
  id: p.id,
  name: p.title,
  category: p.category,
  price: p.price,
  icon: CATEGORY_ICON[p.category] || Sparkles,
  badge: p.badge,
  image: p.thumbnail,
}));

/* ============================================================
   FOOTER
   ============================================================ */

function PlaceholderFooter() {
  return (
    <footer className="lux-footer">
      <div className="lux-footer-inner">

        <div className="lux-footer-col lux-footer-brand">

          <div className="lux-logo lux-logo-footer">
            MAISON&nbsp;&amp;&nbsp;LUXE
          </div>

          <p>
            Fine accessories, crafted with intention.
            Timeless pieces for every story.
          </p>

          <div className="lux-footer-social">

            <a href="#" aria-label="Instagram">
              <FaInstagram size={16} />
            </a>

            <a href="#" aria-label="Facebook">
              <FaFacebookF size={16} />
            </a>

            <a href="#" aria-label="Twitter">
              <FaTwitter size={16} />
            </a>

          </div>

        </div>

        <div className="lux-footer-col">

          <h4>Shop</h4>

          <a href="#">Rings</a>
          <a href="#">Necklaces</a>
          <a href="#">Watches</a>

        </div>

        <div className="lux-footer-col">

          <h4>Support</h4>

          <a href="#">Shipping</a>
          <a href="#">Returns</a>
          <a href="#">Contact Us</a>

        </div>

        <div className="lux-footer-col">

          <h4>Newsletter</h4>

          <p>
            Be first to know about new arrivals.
          </p>

          <div className="lux-footer-form">

            <input
              type="email"
              placeholder="Your email"
            />

            <button>
              Join
            </button>

          </div>

        </div>

      </div>

      <div className="lux-footer-bottom">
        ©️ {new Date().getFullYear()} Maison &amp; Luxe.
        All rights reserved.
      </div>

    </footer>
  );
}

/* ============================================================
   PRODUCT CARD
   ============================================================ */

function ProductCard({ product }) {

  const Icon = product.icon;

  const [imgFailed, setImgFailed] = useState(false);

  const showImage =
    product.image &&
    !imgFailed;

  return (

    <article className="lux-card">

      <div className="lux-card-media">

        {/* PRODUCT IMAGE */}
        {showImage ? (

          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-image-link"
          >

            <img
              src={product.image}
              alt={product.name}
              className="lux-card-img"
              loading="lazy"
              onError={() => setImgFailed(true)}
            />

          </Link>

        ) : (

          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-media-icon"
          >

            <Icon
              size={40}
              strokeWidth={1}
            />

          </Link>

        )}

        {/* BADGE */}
        {product.badge && (
          <span className="lux-card-badge">
            {product.badge}
          </span>
        )}

        {/* QUICK ADD */}
        <button
          className="lux-card-quickadd"
          aria-label={`Add ${product.name} to cart`}
        >

          <ShoppingBag
            size={16}
            strokeWidth={1.5}
          />

        </button>

      </div>

      {/* CARD BODY */}
      <div className="lux-card-body">

        <span className="lux-card-eyebrow">
          {product.category}
        </span>

        <h3 className="lux-card-name">
          {product.name}
        </h3>

        <div className="lux-card-price">
          ${product.price.toFixed(2)}
        </div>

        <div className="lux-card-actions">

          {/* VIEW DETAILS */}
          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-btn lux-btn-outline"
          >
            View Details
          </Link>

          {/* ADD TO CART */}
          <button
            className="lux-btn lux-btn-solid"
            onClick={() => {

              const cart =
                JSON.parse(
                  localStorage.getItem("cart")
                ) || [];

              const existingProduct =
                cart.find(
                  (item) =>
                    item.id === product.id
                );

              if (existingProduct) {

                existingProduct.quantity += 1;

              } else {

                cart.push({
                  id: product.id,
                  name: product.name,
                  price: product.price,
                  quantity: 1,
                  image: product.image,
                });

              }

              localStorage.setItem(
                "cart",
                JSON.stringify(cart)
              );

              alert(
                "Product added to cart successfully!"
              );

            }}
          >
            Add to Cart
          </button>

        </div>

      </div>

    </article>

  );
}

/* ============================================================
   MAIN PAGE
   ============================================================ */

export default function CollectionsPage() {

  const [activeCategory, setActiveCategory] =
    useState("All");

  const filteredProducts = useMemo(() => {

    if (activeCategory === "All") {
      return PRODUCTS;
    }

    return PRODUCTS.filter(
      (product) =>
        product.category === activeCategory
    );

  }, [activeCategory]);

  return (

    <div className="lux-root">

      <style>{`

        ${fontImport}

      `}</style>

      {/* HERO */}

      <section className="lux-hero">

        <div className="lux-hero-eyebrow">
          The Full Edit
        </div>

        <h1>
          Our Collections
        </h1>

        <div className="lux-hero-divider">

          <span className="line" />

          <span className="diamond" />

          <span className="line" />

        </div>

        <p>
          Discover pieces designed to last a lifetime —
          rings, necklaces, bracelets, earrings, chains
          and watches, each finished by hand.
        </p>

      </section>

      {/* FILTERS */}

      <nav
        className="lux-filters"
        aria-label="Product categories"
      >

        {CATEGORIES.map(
          ({ id, label, icon: Icon }) => (

            <button
              key={id}
              className={`lux-filter-btn ${
                activeCategory === id
                  ? "is-active"
                  : ""
              }`}
              onClick={() =>
                setActiveCategory(id)
              }
            >

              <Icon
                size={14}
                strokeWidth={1.5}
              />

              {label}

            </button>

          )
        )}

      </nav>

      {/* PRODUCTS */}

      <section className="lux-grid-section">

        <div className="lux-grid-meta">

          <span>

            Showing{" "}

            <strong>
              {filteredProducts.length}
            </strong>{" "}

            {filteredProducts.length === 1
              ? "piece"
              : "pieces"}

          </span>

          <span>

            {activeCategory === "All"
              ? "All Collections"
              : activeCategory}

          </span>

        </div>

        {filteredProducts.length > 0 ? (

          <div className="lux-grid">

            {filteredProducts.map(
              (product) => (

                <ProductCard
                  key={product.id}
                  product={product}
                />

              )
            )}

          </div>

        ) : (

          <div className="lux-empty">

            No pieces found in this collection yet.

          </div>

        )}

      </section>

      {/* FOOTER */}

      <PlaceholderFooter />

    </div>

  );
}
